files.app/globals.css:
:root {
  --green: #176a45;
  --green-dark: #0f3f2b;
  --yellow: #e4b82f;
  --ink: #18231d;
  --muted: #65736b;
  --surface: #ffffff;
  --line: #dfe7e2;
  --bg: #f4f7f5;
  --danger: #a83232;
}
* { box-sizing: border-box; }
html, body { margin: 0; min-height: 100%; background: var(--bg); color: var(--ink); font-family: Arial, Helvetica, sans-serif; }
a { color: inherit; text-decoration: none; }
button, input, a { font: inherit; -webkit-tap-highlight-color: transparent; }
button { cursor: pointer; }
button:disabled { cursor: not-allowed; opacity: .6; }
.app-shell { min-height: 100vh; display: grid; grid-template-columns: 244px minmax(0, 1fr); }
.sidebar { padding: 24px 16px; background: var(--green-dark); color: white; display: flex; flex-direction: column; gap: 28px; }
.brand { display: flex; align-items: center; gap: 12px; padding: 4px 8px; }
.brand-mark { width: 42px; height: 42px; border-radius: 14px; display: grid; place-items: center; color: #173e2c; background: #f1c94d; flex: 0 0 auto; }
.brand strong, .brand span { display: block; }
.brand span { color: #b9d0c4; font-size: 12px; margin-top: 2px; }
.sidebar nav { display: grid; gap: 8px; }
.nav-link { min-height: 48px; display: flex; align-items: center; gap: 12px; padding: 0 14px; border-radius: 13px; color: #c8d8d0; font-weight: 700; }
.nav-link:hover, .nav-link.active { background: rgba(255,255,255,.12); color: white; }
.staging-note { margin-top: auto; font-size: 12px; line-height: 1.5; color: #a9c3b6; padding: 12px; border-top: 1px solid rgba(255,255,255,.14); }
.main-content { min-width: 0; padding: 30px; }
.topbar { display: flex; gap: 24px; align-items: center; justify-content: space-between; margin-bottom: 28px; }
.topbar h1 { margin: 5px 0 0; font-size: clamp(26px, 4vw, 38px); }
.topbar-actions { display: flex; align-items: center; gap: 8px; }
.eyebrow { color: var(--green); font-weight: 900; letter-spacing: .08em; font-size: 11px; }
.identity-chip { display: flex; gap: 10px; align-items: center; padding: 9px 12px; border: 1px solid var(--line); border-radius: 16px; background: white; }
.initials { width: 40px; height: 40px; border-radius: 50%; display: grid; place-items: center; font-weight: 900; color: white; background: var(--green); }
.identity-chip strong, .identity-chip span { display: block; }
.identity-chip span { color: var(--muted); font-size: 12px; margin-top: 2px; }
.panel { background: var(--surface); border: 1px solid var(--line); border-radius: 22px; box-shadow: 0 12px 34px rgba(29, 53, 40, .06); }
.hero { padding: clamp(24px, 5vw, 46px); display: grid; grid-template-columns: 1.4fr .6fr; gap: 28px; align-items: center; }
.hero h2 { margin: 10px 0 14px; max-width: 680px; font-size: clamp(28px, 5vw, 50px); line-height: 1.04; letter-spacing: -.04em; }
.hero p { color: var(--muted); font-size: 16px; line-height: 1.7; max-width: 720px; }
.metric-placeholder { border-radius: 18px; padding: 24px; background: #edf6f1; border: 1px dashed #9fc9b2; text-align: center; }
.metric-placeholder span, .metric-placeholder small { display: block; color: var(--muted); }
.metric-placeholder strong { display: block; font-size: 62px; color: var(--green); margin: 8px 0; }
.capability-grid { margin-top: 18px; display: grid; grid-template-columns: repeat(4, minmax(0,1fr)); gap: 14px; }
.capability-card { padding: 20px; }
.capability-card h3 { margin: 12px 0 8px; }
.capability-card p { margin: 0; color: var(--muted); line-height: 1.5; font-size: 14px; }
.status-dot { width: 10px; height: 10px; display: inline-block; border-radius: 50%; }
.status-dot.ready { background: #2ca66b; }
.status-dot.pending { background: var(--yellow); }
.empty-state { padding: 52px; max-width: 900px; }
.empty-state h2 { font-size: 34px; margin: 10px 0; }
.empty-state p { color: var(--muted); line-height: 1.7; max-width: 700px; }
footer { text-align: center; color: #708077; font-size: 12px; padding: 32px 0 8px; }

.login-page { min-height: 100vh; display: grid; place-items: center; align-content: center; padding: 24px; }
.login-card { width: min(460px, 100%); padding: 34px; }
.login-brand { padding: 0; margin-bottom: 34px; }
.login-brand span { color: var(--muted); }
.login-card h1 { margin: 8px 0 10px; font-size: 38px; }
.login-card > p { color: var(--muted); line-height: 1.6; }
.login-form { display: grid; gap: 16px; margin-top: 26px; }
.login-form label, .answer-field { display: grid; gap: 7px; font-size: 13px; font-weight: 800; }
.login-form input, .answer-field input { min-height: 48px; border: 1px solid #cdd9d2; border-radius: 12px; padding: 10px 13px; background: white; color: var(--ink); outline: none; }
.login-form input:focus, .answer-field input:focus { border-color: var(--green); box-shadow: 0 0 0 3px rgba(23,106,69,.11); }
.primary-button, .secondary-button, .text-button, .listen-button, .icon-button { border: 0; border-radius: 12px; min-height: 44px; padding: 0 16px; font-weight: 800; display: inline-flex; align-items: center; justify-content: center; gap: 8px; }
.primary-button { background: var(--green); color: white; }
.primary-button:hover:not(:disabled) { background: #115d3b; }
.secondary-button { background: #edf4f0; color: var(--green-dark); border: 1px solid #d6e4dc; }
.text-button { background: transparent; color: var(--muted); }
.listen-button { background: #fff8dc; color: #6d5610; border: 1px solid #ead995; }
.icon-button { width: 46px; padding: 0; background: white; border: 1px solid var(--line); color: var(--ink); }
.inline-button { margin-top: 14px; width: fit-content; }
.form-error { padding: 11px 13px; border-radius: 11px; background: #fff1f1; color: var(--danger); border: 1px solid #f0caca; font-size: 13px; line-height: 1.45; }
.form-note, .sync-note { padding: 10px 12px; border-radius: 11px; background: #edf6f1; color: var(--green-dark); border: 1px solid #d4e8dd; font-size: 13px; line-height: 1.45; }
.page-error { margin-bottom: 16px; }
.sync-note { display: inline-flex; align-items: center; gap: 8px; margin-bottom: 14px; }
.loading-page { min-height: 100vh; display: flex; align-items: center; justify-content: center; gap: 10px; font-weight: 800; color: var(--green-dark); }
.spin { animation: spin 1s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }

.dashboard-hero { grid-template-columns: 1.25fr .55fr; }
.route-score { border-radius: 20px; padding: 25px; background: #edf6f1; border: 1px solid #d5e9de; text-align: center; }
.route-score span, .route-score small { display: block; color: var(--muted); }
.route-score span { font-size: 11px; font-weight: 900; letter-spacing: .07em; }
.route-score strong { display: block; font-size: 58px; line-height: 1; color: var(--green); margin: 10px 0; }
.metric-grid { margin-top: 16px; display: grid; grid-template-columns: repeat(4, minmax(0,1fr)); gap: 14px; }
.metric-card { padding: 20px; }
.metric-card span { display: block; color: var(--muted); font-size: 12px; font-weight: 800; }
.metric-card strong { display: block; margin-top: 7px; font-size: 34px; color: var(--green-dark); }
.backend-stats { margin-top: 16px; display: grid; grid-template-columns: repeat(4,minmax(0,1fr)); padding: 18px; gap: 8px; }
.backend-stats > div { padding: 12px 16px; border-right: 1px solid var(--line); }
.backend-stats > div:last-child { border-right: 0; }
.backend-stats span, .backend-stats strong { display: block; }
.backend-stats span { color: var(--muted); font-size: 12px; }
.backend-stats strong { margin-top: 4px; font-size: 22px; }
.empty-inline { display: inline-block; margin-top: 12px; padding: 10px 12px; background: #f5f7f6; border-radius: 10px; color: var(--muted); font-size: 13px; }

.profile-panel, .progress-panel, .lesson-start, .practice-card, .lesson-finish, .lesson-result { padding: clamp(24px, 4vw, 42px); max-width: 980px; }
.profile-panel h2, .progress-panel h2, .lesson-start h2, .practice-card h2, .lesson-finish h2, .lesson-result h2 { margin: 9px 0 16px; font-size: clamp(27px,4vw,40px); }
.profile-grid { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 12px; margin: 25px 0 0; }
.profile-grid > div { padding: 17px; border-radius: 14px; background: #f6f8f7; }
.profile-grid dt { color: var(--muted); font-size: 12px; font-weight: 800; }
.profile-grid dd { margin: 5px 0 0; font-weight: 900; }
.lesson-progress-list { display: grid; gap: 10px; margin-top: 24px; }
.lesson-progress-row { display: flex; justify-content: space-between; gap: 20px; align-items: center; padding: 15px 17px; border: 1px solid var(--line); border-radius: 14px; }
.lesson-progress-row div:last-child { text-align: right; }
.lesson-progress-row strong, .lesson-progress-row span { display: block; }
.lesson-progress-row span { color: var(--muted); font-size: 12px; margin-top: 4px; }
.muted-copy { color: var(--muted); }
.lesson-actions { display: flex; flex-wrap: wrap; gap: 9px; margin-top: 24px; }
.practice-head { display: flex; justify-content: space-between; gap: 20px; align-items: flex-start; }
.practice-head p, .lesson-start p, .lesson-finish p, .lesson-result p { color: var(--muted); line-height: 1.6; }
.task-counter { flex: 0 0 auto; border-radius: 999px; background: #edf6f1; color: var(--green); padding: 8px 11px; font-weight: 900; font-size: 12px; }
.answer-field { margin-top: 22px; }
.answer-field input { font-size: 18px; }
.listen-button { margin: 8px 0 2px; }
.server-feedback { margin-top: 16px; padding: 12px 13px; border-radius: 12px; font-weight: 800; font-size: 13px; }
.server-feedback.correct { background: #eaf7ef; color: #176a45; }
.server-feedback.incorrect { background: #fff0f0; color: #963535; }
.form-note { margin-top: 14px; }
.result-score { display: flex; align-items: baseline; gap: 14px; margin: 22px 0; }
.result-score strong { font-size: 64px; color: var(--green); }
.result-score span { color: var(--muted); }
.role-home { grid-template-columns: 1fr; }

@media (max-width: 920px) {
  .app-shell { grid-template-columns: 1fr; }
  .sidebar { position: sticky; top: 0; z-index: 10; padding: 10px; gap: 10px; }
  .brand, .staging-note { display: none; }
  .sidebar nav { grid-template-columns: repeat(6, minmax(68px,1fr)); overflow-x: auto; }
  .nav-link { justify-content: center; flex-direction: column; gap: 3px; padding: 7px 4px; font-size: 11px; min-height: 54px; }
  .main-content { padding: 20px; }
  .hero, .dashboard-hero { grid-template-columns: 1fr; }
  .capability-grid, .metric-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }
  .backend-stats { grid-template-columns: repeat(2,minmax(0,1fr)); }
  .backend-stats > div { border-right: 0; border-bottom: 1px solid var(--line); }
}
@media (max-width: 560px) {
  .sidebar nav { grid-template-columns: repeat(6, 74px); }
  .topbar { align-items: flex-start; }
  .identity-chip { display: none; }
  .main-content { padding: 16px; }
  .hero { padding: 24px 20px; }
  .capability-grid, .metric-grid, .profile-grid, .backend-stats { grid-template-columns: 1fr; }
  .empty-state { padding: 30px 22px; }
  .practice-head, .lesson-progress-row { flex-direction: column; }
  .lesson-progress-row div:last-child { text-align: left; }
  .result-score { display: block; }
}

